// 手写的裸名试验件：只验「主进程里的 loader 能不能按 home 把我挂上」。
// 挂上就在全局留个记号，探针据此判真挂上了，不只看日志。
export const name = 'gwb-probe-hello'

export function apply(ctx) {
  globalThis.__probeHelloMounted = { at: Date.now(), inElectron: typeof process.versions.electron === 'string' }
  ctx.logger('probe-hello').info('mounted in', process.type ?? 'unknown')
}
